<script setup lang="ts">
import {localize} from './localization';

import {computed,ref,watch} from 'vue';
import {useSession} from './store';
import {useDraftHistory} from './modules/useDraftHistory';
import {vDecimal} from './modules/decimal-input';
import {measurementLabel} from './modules/model-labels';
const props=defineProps<{language:'zh'|'en'}>(),store=useSession(),zh=computed(()=>props.language==='zh'),surface=computed(()=>store.data.project?.surface),targets=ref<Record<string,number>>({}),weights=ref<Record<string,number>>({}),sculpt=ref({center:{xMm:0,yMm:0,zMm:0},radiusMm:100,delta:{xMm:0,yMm:0,zMm:5},mode:'move' as 'move'|'smooth',strength:.5}),vertexId=ref(''),vertexPage=ref(1),sculptOpen=ref(false);
const historyPanel=ref<HTMLElement>(),history=useDraftHistory(()=>({targets:targets.value,weights:weights.value,sculpt:sculpt.value}),v=>{targets.value=v.targets;weights.value=v.weights;sculpt.value=v.sculpt;},()=>!!historyPanel.value?.getClientRects().length,()=>store.busy);
const vertexWindow=computed(()=>surface.value?.vertices.slice((vertexPage.value-1)*200,vertexPage.value*200)??[]);
watch(()=>surface.value?.id,()=>{vertexPage.value=1;vertexId.value='';});
watch(()=>JSON.stringify([surface.value?.id,surface.value?.template?.measurements,surface.value?.customTemplate?.weights]),()=>{history.reset(()=>{const mesh=surface.value;targets.value=Object.fromEntries((mesh?.template?.measurements??[]).map(m=>[m.name,m.actualMm]));weights.value={...mesh?.customTemplate?.weights};});},{immediate:true});
function centerOnVertex(){const v=surface.value?.vertices.find(v=>v.id===vertexId.value);if(v)sculpt.value.center={xMm:v.xMm,yMm:v.yMm,zMm:v.zMm};}
async function fit(){const p=store.data.project;if(p)await store.run(()=>window.fpcad.fitSpecies(p.id,p.revision,JSON.parse(JSON.stringify(targets.value))));}
async function morph(){const p=store.data.project;if(p)await store.run(()=>window.fpcad.morphTemplate(p.id,p.revision,JSON.parse(JSON.stringify(weights.value))));}
async function applySculpt(){const p=store.data.project;if(p)await store.run(()=>window.fpcad.sculptSurface(p.id,p.revision,JSON.parse(JSON.stringify(sculpt.value))));}
</script>
<template><section v-if="surface" ref="historyPanel" class="mesh-edit-panel">
<details v-if="surface.source==='species-template-1'&&surface.template"><summary>{{zh?'内置模板：实测尺寸拟合':localize('Built-in template: measured dimensions fit')}}</summary><p>{{zh?'目标为部位参考面的实测尺寸，包含当前填充和层厚；躯干围度不包含手臂、翼或尾部。连续网格会自动重新生成。左右共用参数，目标差异超过 1 mm 会拒绝。拟合后请重新裁切。':localize('Targets measure each part reference surface including padding and layers; torso girths exclude arms, wings and tail. The continuous shell regenerates automatically. Paired limbs share parameters; differing targets over 1 mm are rejected. Recompute cuts after fitting.')}}</p><div class="mesh-inputs"><label v-for="(value,key) in targets" :key="key">{{measurementLabel(String(key),zh)}} mm<input v-decimal v-model.number="targets[key]" :aria-label="'Species target '+key+' mm'" type="number" step=".01" min="1"></label></div><button :disabled="store.busy" @click="fit">{{zh?'拟合实测目标（1 mm 公差）':localize('Fit measured targets (1 mm tolerance)')}}</button><p v-if="surface.template?.fit">{{zh?'拟合迭代':localize('Fit iterations')}} {{surface.template.fit.iterations}}</p></details>
<details v-if="surface.source==='custom-template-1'&&surface.customTemplate"><summary>{{zh?'显式 Morph 权重':localize('Explicit Morph weights')}}</summary><div class="mesh-inputs"><label v-for="m in surface.customTemplate.definition.morphs" :key="m.name">{{m.name}} [{{m.minWeight}}, {{m.maxWeight}}]<input v-model.number="weights[m.name]" v-decimal type="number" :min="m.minWeight" :max="m.maxWeight" step=".01"></label></div><button :disabled="store.busy" @click="morph">{{zh?'应用有界 Morph':localize('Apply bounded Morph')}}</button></details>
<details @toggle="sculptOpen=($event.target as HTMLDetailsElement).open"><summary>{{zh?'局部雕刻与平滑':localize('Local sculpt and smoothing')}}</summary><template v-if="sculptOpen"><p>{{zh?'在毫米球形范围内使用平滑衰减权重。拒绝退化与局部翻面；旧展开失效，生成/拟合模板会替换雕刻结果。仍需检查全局自碰撞并试制。':localize('Smooth falloff within a millimetre sphere. Degenerate or locally inverted faces are rejected; unwrap becomes stale. Template generation or fitting replaces sculpted geometry. Review global intersections and physical trials.')}}</p><label v-if="surface.vertices.length>200">{{zh?'顶点列表页，每页 200 个':localize('Vertex page, 200 per page')}}<input v-model.number="vertexPage" aria-label="Sculpt vertex page" v-decimal type="number" min="1" :max="Math.ceil(surface.vertices.length/200)"></label><select v-model="vertexId" @change="centerOnVertex"><option value="">{{zh?'选择中心顶点':localize('Choose centre vertex')}}</option><option v-for="(v,i) in vertexWindow" :key="v.id" :value="v.id">{{(vertexPage-1)*200+i+1}} · {{v.xMm.toFixed(1)}}, {{v.yMm.toFixed(1)}}, {{v.zMm.toFixed(1)}}</option></select><div class="mesh-inputs"><label v-for="axis in (['xMm','yMm','zMm'] as const)" :key="axis">{{zh?'中心':localize('Centre')}} {{axis}}<input v-model.number="sculpt.center[axis]" v-decimal type="number"></label><label>{{zh?'半径 mm':localize('Radius mm')}}<input v-model.number="sculpt.radiusMm" v-decimal type="number" min=".01"></label><label>{{zh?'强度':localize('Strength')}}<input v-model.number="sculpt.strength" v-decimal type="number" min=".001" max="1" step=".05"></label><label v-for="axis in (['xMm','yMm','zMm'] as const)" :key="'delta'+axis">Δ {{axis}}<input v-model.number="sculpt.delta[axis]" v-decimal type="number" min="-1000" max="1000"></label></div><select v-model="sculpt.mode"><option value="move">{{zh?'局部位移':localize('Local move')}}</option><option value="smooth">{{zh?'邻域平滑':localize('Neighbour smoothing')}}</option></select><button :disabled="store.busy" @click="applySculpt">{{zh?'应用雕刻（可撤销）':localize('Apply sculpt (undoable)')}}</button><p v-if="surface.sculpt">{{surface.sculpt.mode}} · {{surface.sculpt.affectedVertices}} {{zh?'顶点':localize('vertices')}}</p></template></details>
</section></template>
<style scoped>.mesh-edit-panel{padding:8px 0}.mesh-inputs{display:flex;flex-wrap:wrap;gap:10px}.mesh-inputs label{width:150px}.mesh-edit-panel p{line-height:1.5}</style>
